#!/usr/bin/env python3
"""Compare exact Go source sections in frozen before/after production builds."""
import argparse
import difflib
import hashlib
import json
from pathlib import Path
import re


MARKER = re.compile(rb'^// gopurs-source-v1: ([0-9a-f]+)\r?\n', re.MULTILINE)


def sha(data):
    return hashlib.sha256(data).hexdigest()


def inventory(build):
    build = build.resolve()
    output = build / 'output'
    manifest_bytes = (build / 'manifest.json').read_bytes()
    manifest = json.loads(manifest_bytes)
    binary_sha256 = sha((build / 'benchmark').read_bytes())
    if binary_sha256 != manifest['binary_sha256']:
        raise ValueError(f'Changed benchmark binary: {build}')
    sections, files, standalone, headers = {}, {}, {}, {}
    for path in sorted(output.rglob('*.go')):
        relative = str(path.relative_to(output))
        data = path.read_bytes()
        files[relative] = sha(data)
        markers = list(MARKER.finditer(data))
        if not markers:
            standalone[relative] = data
            continue
        headers[relative] = data[:markers[0].start()]
        for index, marker in enumerate(markers):
            name = bytes.fromhex(marker.group(1).decode('ascii')).decode('utf-8')
            key = str(path.relative_to(output).parent / name)
            if key in sections:
                raise ValueError(f'Duplicate source section: {key}')
            end = markers[index + 1].start() if index + 1 < len(markers) else len(data)
            sections[key] = data[marker.end():end]
    if not sections:
        raise ValueError(f'No Go module sections found: {build}')
    provenance = {'directory': str(build), 'manifest_sha256': sha(manifest_bytes),
                  'binary_sha256': binary_sha256, 'generated_files_sha256': files}
    return {'sections': sections, 'headers': headers, 'standalone': standalone,
            'provenance': provenance}


def compare(before_path, after_path):
    before, after = inventory(before_path), inventory(after_path)
    results = {'builds': {'before': before['provenance'], 'after': after['provenance']}}
    for category in ['sections', 'headers', 'standalone']:
        old, new = before[category], after[category]
        rows = {}
        for name in sorted(set(old) | set(new)):
            rows[name] = {'before_sha256': sha(old[name]) if name in old else None,
                          'after_sha256': sha(new[name]) if name in new else None,
                          'identical': old.get(name) == new.get(name)}
            if not rows[name]['identical']:
                rows[name]['diff'] = ''.join(difflib.unified_diff(
                    old.get(name, b'').decode('utf-8').splitlines(True),
                    new.get(name, b'').decode('utf-8').splitlines(True),
                    fromfile='before/' + name, tofile='after/' + name))
        results[category] = {'counts': {'before': len(old), 'after': len(new)},
                             'changed': [name for name, row in rows.items() if not row['identical']],
                             'sha256': rows}
    expected = {name for name in before['sections'] if Path(name).name == 'Test_StateMonad.go'}
    unexpected = set(results['sections']['changed']) - expected
    results['scope_check'] = {'target_module_basename': 'Test_StateMonad.go',
                              'additional_changed_sections': sorted(unexpected),
                              'only_state_changed': not unexpected and
                                  not results['headers']['changed'] and
                                  not results['standalone']['changed']}
    return results


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--before-core', type=Path, required=True)
    parser.add_argument('--after-core', type=Path, required=True)
    parser.add_argument('--before-all', type=Path, required=True)
    parser.add_argument('--after-all', type=Path, required=True)
    parser.add_argument('--output', type=Path, required=True)
    args = parser.parse_args()
    result = {'method': 'Byte-identical Go sections split by gopurs-source-v1 markers; headers, runtime and other Go files checked separately.',
              'script_sha256': sha(Path(__file__).read_bytes()),
              'core': compare(args.before_core, args.after_core),
              'all': compare(args.before_all, args.after_all)}
    args.output.write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n')
    for name in ['core', 'all']:
        row = result[name]
        print(json.dumps({'scope': name, 'section_counts': row['sections']['counts'],
                          'changed_sections': row['sections']['changed'],
                          'changed_headers': row['headers']['changed'],
                          'changed_other_files': row['standalone']['changed'],
                          'scope_check': row['scope_check']}, ensure_ascii=False))
    if not all(result[name]['scope_check']['only_state_changed'] for name in ['core', 'all']):
        print('Additional generated Go changes are recorded with exact diffs for review before timing.')


if __name__ == '__main__':
    main()

